	      cost:String(item.cost || 'Nog checken').trim(),
	      stimulus:String(item.stimulus || 'Middel').trim(),
	      fit:String(item.fit || item.note || 'Automatisch gevonden. Check details voordat je dit plant.').trim(),
	      source:String(item.source || 'Broncheck').trim(),
